    """Reduce a SAT instance to a Clique instance.

    ``instance`` is ``{"num_vars": m, "clauses": [[literal, ...], ...]}``.
    The result is ``{"n": n, "edges": [[u, v], ...], "k": k}``.
    """
    clauses = instance["clauses"]

